INSERT INTO pill_readings (device_id, time_utc, temperature_c, gravity_sg, gravity_velocity_sg_per_day, battery_percent, rssi_dbm, paired_temp_controller)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
ON CONFLICT (device_id, time_utc) DO NOTHING;

